#!/usr/bin/env python3
"""Grade 12 standalone optional-worksheet content (Project Plan item 8).

Separate, new pipeline from data/grade12.ts (the 187-day lesson sequence).
Builds exactly 10 worksheets per subject x 4 subjects = 40 worksheets,
15 multiple-choice questions each, for Grade 12 four subjects: English,
AdvancedFunctions, Calculus, Physics.

Content is organized into 10 practice themes per subject spanning that
subject typical Ontario Grade 12 scope (English: literary study and
composition; AdvancedFunctions (MHF4U): polynomial/rational/exponential/
log/trig functions plus discrete math; Calculus (MCV4U): limits,
derivatives, curve sketching, related rates, vectors, lines and planes;
Physics (SPH4U): kinematics, dynamics, energy/momentum, fields,
electromagnetism, waves, relativity, quantum). Themes progress roughly
foundational-to-advanced within each subject.

Raw content is written as (question, correct_answer, [wrong, wrong, wrong])
tuples; build_mc() below shuffles each worksheet correct-answer index
across A/B/C/D (target distribution close to even) before calling the
shared mc() helper, so no single option letter is biased across a
worksheet. Every mc() call ultimately goes through gen_worksheets.mc(),
which enforces the schema (4 options, valid 0-indexed answer, no stray
quote characters). No embedded straight double-quotes or apostrophes
anywhere -- contractions/possessives are dropped or written without the
apostrophe (e.g. "Newtons law", "does not"), matching the day-based
curriculum convention.
"""
import random
import sys
import os
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from gen_worksheets import mc, worksheet, write_worksheets

RNG = random.Random(20260820)


def build_mc(raw_questions):
    """raw_questions: list of (q, correct_text, [wrong, wrong, wrong]).
    Returns a list of mc() tuples with correct-answer index rebalanced
    roughly evenly across the four option slots within this worksheet."""
    n = len(raw_questions)
    targets = [i % 4 for i in range(n)]
    RNG.shuffle(targets)
    result = []
    for i, (q, correct, wrongs) in enumerate(raw_questions):
        target = targets[i]
        opts = [None, None, None, None]
        opts[target] = correct
        w = list(wrongs)
        RNG.shuffle(w)
        wi = 0
        for slot in range(4):
            if opts[slot] is None:
                opts[slot] = w[wi]
                wi += 1
        result.append(mc(q, opts, target))
    return result


def WS(subject, number, title, raw_questions):
    assert len(raw_questions) == 15, f'{title!r}: expected 15 raw questions, got {len(raw_questions)}'
    return worksheet(subject, number, title, build_mc(raw_questions))


